from pathlib import Path
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone, timedelta
import hashlib, json, requests

root = Path.cwd()
out = root / "reports/research/510300_original_operating_counterexample_causes_v1"
def now():
    return datetime.now(timezone(timedelta(hours=8))).isoformat()
def digest(data):
    return hashlib.sha256(data).hexdigest()
def save(name, value):
    path = out / name
    if path.exists():
        raise RuntimeError("该产物已存在，禁止覆盖或重复运行：" + str(path))
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return {"path": str(path.relative_to(root)), "sha256": digest(path.read_bytes())}
protocol_bytes = (out / "protocol.json").read_bytes()
if digest(protocol_bytes) != "5b8eb8910af2db2eadcee6ecfe8d596077f69fa19d57615e921ded6eadfb4af6":
    raise RuntimeError("冻结口径身份不符")
protocol = json.loads(protocol_bytes)
for parent in protocol["parents"]:
    if digest((root / parent["path"]).read_bytes()) != parent["sha256"]:
        raise RuntimeError("原父证据身份不符：" + parent["path"])
selections = [
    {"economic_period": "2019M04", "url": "https://www.stats.gov.cn/sj/sjjd/202302/t20230202_1896187.html", "returned_title": "国家统计局工业司高级统计师朱虹解读2019年1—4月份工业企业利润数据", "locator_batch": 0, "status": "SELECTED_FIRST_RETURNED_ORIGINAL_NATIONAL_CAUSE"},
    {"economic_period": "2019M05", "url": None, "locator_batch": 0, "status": "UNKNOWN_LOCATOR_NO_MATCHING_ORIGINAL_CAUSE"},
    {"economic_period": "2019M06", "url": None, "locator_batch": 0, "status": "UNKNOWN_LOCATOR_NO_MATCHING_ORIGINAL_CAUSE"},
    {"economic_period": "2023M12", "url": "https://www.stats.gov.cn/xxgk/jd/sjjd2020/202401/t20240127_1946918.html", "returned_title": "国家统计局信息公开；国家统计局工业司统计师于卫宁解读工业企业利润数据", "locator_batch": 1, "status": "SELECTED_FIRST_RETURNED_ORIGINAL_NATIONAL_CAUSE_PUBLICATION_CLOCK_PENDING"},
    {"economic_period": "2024M02", "url": "https://www.stats.gov.cn/sj/sjjd/202403/t20240327_1948174.html", "returned_title": "国家统计局工业司统计师于卫宁解读工业企业利润数据", "locator_batch": 1, "status": "SELECTED_FIRST_RETURNED_ORIGINAL_NATIONAL_CAUSE"}
]
for item in selections:
    batch = json.loads((out / ("固定定位批次" + str(item["locator_batch"]) + ".json")).read_text(encoding="utf-8-sig"))
    serialized = json.dumps(batch, ensure_ascii=False)
    if item["url"] and item["url"] not in serialized:
        raise RuntimeError("候选不在已实际返回的固定定位批次：" + item["economic_period"])
selected = [item for item in selections if item["url"]]
if len(selected) != 3 or len({item["url"] for item in selected}) != 3:
    raise RuntimeError("固定原载体集合发生变化")
save("固定五原期_原原因载体选择及未知保留_E111.json", {
    "experiment_id": "E111", "selected_at": now(), "actual_fixed_queries": 5,
    "selected_first_GET_count": 3, "extra_queries": 0, "alternate_carriers": 0,
    "selections": selections,
    "excluded_returned_roles": ["工业利润原数量通报，不作为另一个原因解读", "2014/2015等错误原年", "2019M03及2024M04/M05等错误原累计期", "2024-04-17等迟于原共同截止的后来综述", "2025/2026错误原年"],
    "2023M12_clock_note": "检索摘要只见成文日期，不据此承认历史公开钟；以选定同原HTML自身证据裁定，不换载体"
})
def fetch(item):
    period = item["economic_period"]
    claim = save(period + "_唯一首次GET认领_E111.json", {"claimed_at": now(), "url": item["url"], "attempt": 1, "retries": 0, "TLS_verify": True, "authenticated_request": False})
    started = now()
    record = {"economic_period": period, "requested_url": item["url"], "started_at": started, "claim": claim, "attempt": 1, "retries": 0, "TLS_verify": True, "authenticated_request": False}
    try:
        response = requests.get(item["url"], timeout=(12, 30), verify=True, allow_redirects=False)
        record.update({"status_code": response.status_code, "response_url": response.url, "location": response.headers.get("Location"), "content_type": response.headers.get("Content-Type"), "bytes": len(response.content), "ended_at": now()})
        raw_path = out / (period + "_唯一首次取得原载体_E111.html")
        if raw_path.exists():
            raise RuntimeError("原载体已存在，禁止覆盖")
        raw_path.write_bytes(response.content)
        record["raw_path"] = str(raw_path.relative_to(root))
        record["raw_sha256"] = digest(response.content)
        record["status"] = "FIRST_GET_HTTP_200_RAW_SAVED" if response.status_code == 200 else "UNKNOWN_FIRST_GET_NON_200_NO_RETRY"
    except Exception as exc:
        record.update({"ended_at": now(), "status": "UNKNOWN_FIRST_GET_TRANSPORT_FAILURE_NO_RETRY", "error_type": type(exc).__name__, "error": str(exc)})
    save(period + "_唯一首次GET回执_E111.json", record)
    return record
results = []
with ThreadPoolExecutor(max_workers=3) as pool:
    futures = [pool.submit(fetch, item) for item in selected]
    for future in as_completed(futures):
        record = future.result()
        results.append(record)
        print(json.dumps({key: record.get(key) for key in ("economic_period", "status", "status_code", "bytes")}, ensure_ascii=False), flush=True)
results.sort(key=lambda item: item["economic_period"])
save("五原期有限首次取得完成_E111.json", {"experiment_id": "E111", "completed_at": now(), "actual_queries": 5, "actual_distinct_first_GETs": len(results), "retries": 0, "alternate_carrier_GETs": 0, "authenticated_requests": 0, "results": results, "missing_locator_periods": ["2019M05", "2019M06"], "source_route_closed_after_this_finite_batch": True})
